def normalize_active_seats(apps, schema_editor):
    """Attribue une place unique aux réservations actives existantes.

    Certaines données de démonstration contiennent plusieurs réservations
    actives avec le même numéro de place. La contrainte d'unicité ne peut être
    ajoutée qu'après cette normalisation.
    """
    Booking = apps.get_model('workshops', 'Booking')
    Workshop = apps.get_model('workshops', 'Workshop')

    for workshop in Workshop.objects.all().iterator():
        capacity = workshop.capacity or 0
        active = list(
            Booking.objects.filter(
                workshop=workshop,
                status__in=['confirmed', 'attended'],
            ).order_by('booked_at', 'pk')
        )
        if not active:
            continue

        used = set()
        to_assign = []
        for booking in active:
            seat = booking.seat_number
            if (
                capacity
                and seat
                and 1 <= seat <= capacity
                and seat not in used
            ):
                used.add(seat)
            else:
                to_assign.append(booking)

        free_seats = (
            number for number in range(1, capacity + 1)
            if number not in used
        )
        changed = []
        for booking in to_assign:
            new_seat = next(free_seats, None) if capacity else None
            if booking.seat_number != new_seat:
                booking.seat_number = new_seat
                changed.append(booking)

        if changed:
            Booking.objects.bulk_update(changed, ['seat_number'])


